    char grid[2][55][55];

    for (int i = 0; i < n; i++) {
        scanf("%s", grid[0][i]);
    }

    int cur = 0;
    int dr[] = {-1, -1, -1,  0, 0,  1, 1, 1};
    int dc[] = {-1,  0,  1, -1, 1, -1, 0, 1};

    for (int step = 0; step < q; step++) {
        int nxt = 1 - cur;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                int live_neighbors = 0;
                for (int d = 0; d < 8; d++) {
                    int nr = r + dr[d];
                    int nc = c + dc[d];
                    if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                        if (grid[cur][nr][nc] == '1') {
                            live_neighbors++;
                        }
                    }
                }

                if (grid[cur][r][c] == '1') {
                    if (live_neighbors == 2 || live_neighbors == 3) {
                        grid[nxt][r][c] = '1';
                    } else {
                        grid[nxt][r][c] = '0';
                    }
                } else {
                    if (live_neighbors == 3) {
                        grid[nxt][r][c] = '1';
                    } else {
                        grid[nxt][r][c] = '0';
                    }
                }
            }
            grid[nxt][r][n] = '\0';
        }
        cur = nxt;
    }

    for (int i = 0; i < n; i++) {
        printf("%s\n", grid[cur][i]);
    }

    return 0;
}
